// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testRegression_property() public {
        vm.deal(address(c), 10 ether);
        address receiver = address(0x123);
        uint amount = 1 ether;
        uint balanceBefore = address(c).balance;
        c.sendTo(receiver, amount);
        uint balanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore - amount);
    }
}
